/** Proposed real native device/storage/menu/display tests; not a runtime result. */
public final class ThresholdSwitchGameTests {
    private static final String STRUCTURE="create_test:reservoir";
    private static final BlockPos S=new BlockPos(3,6,4),T=S.east(),L=S.west(),D=S.south(4);
    private static ThresholdSwitchBlockEntity sensor(GameTestHelper h){return h.getBlockEntity(S,ThresholdSwitchBlockEntity.class);}
    private static ThresholdSwitchBlockEntity barrel(GameTestHelper h){h.setBlock(T,Blocks.BARREL);h.setBlock(S,AllBlocks.THRESHOLD_SWITCH.defaultBlockState().setValue(ThresholdSwitchBlock.FACING,Direction.EAST));var sensor=sensor(h);sensor.updateCurrentLevel();return sensor;}
    private static void amount(GameTestHelper h,int count){var barrel=h.getBlockEntity(T,BarrelBlockEntity.class);barrel.clearContent();int remaining=count;for(int slot=0;remaining>0;slot++){int amount=Math.min(64,remaining);barrel.setItem(slot,new ItemStack(Items.IRON_INGOT,amount));remaining-=amount;}barrel.setChanged();sensor(h).updateCurrentLevel();}
    private static ThresholdSwitchBlockEntity tank(GameTestHelper h,long amount){h.setBlock(T,AllBlocks.FLUID_TANK);h.setBlock(S,AllBlocks.THRESHOLD_SWITCH.defaultBlockState().setValue(ThresholdSwitchBlock.FACING,Direction.EAST));var tank=h.getBlockEntity(T,FluidTankBlockEntity.class);try(var tx=Transaction.openOuter()){h.assertTrue(tank.storage().insert(FluidVariant.of(net.minecraft.world.level.material.Fluids.WATER),amount,tx)==amount,"Actual native tank accepts fixture fluid");tx.commit();}sensor(h).updateCurrentLevel();return sensor(h);}
    private static DisplayLinkBlockEntity display(GameTestHelper h,boolean progress){h.setBlock(D.below(),Blocks.STONE);h.setBlock(D,Blocks.OAK_SIGN);h.setBlock(L,AllBlocks.DISPLAY_LINK.defaultBlockState().setValue(DisplayLinkBlock.FACING,Direction.WEST));var link=h.getBlockEntity(L,DisplayLinkBlockEntity.class);link.target(h.absolutePos(D));var config=new CompoundTag();config.putString("Id",AllDisplaySources.FILL_LEVEL.getId().toString());config.putInt("Mode",progress?1:0);h.assertTrue(link.configure(config,0),"Actual threshold source and native sign configuration");return link;}
    private static String sign(GameTestHelper h){return h.getBlockEntity(D,SignBlockEntity.class).getText(SignTextSlot.FRONT).getMessages(false).getFirst().getString();}
    private static ServerPlayer player(GameTestHelper h){var player=h.makeMockServerPlayerInLevel();player.setGameMode(GameType.SURVIVAL);player.setPos(Vec3.atCenterOf(h.absolutePos(S)).add(0,0,2));return player;}
    private static void load(GameTestHelper h,ThresholdSwitchBlockEntity sensor,CompoundTag tag){sensor.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,h.getLevel().registryAccess(),tag));}

    @GameTest(structure=STRUCTURE) public void actualRegistryAndOriginalItemIdentity(GameTestHelper h){var s=barrel(h);h.assertTrue(s.getType()==AllBlockEntityTypes.THRESHOLD_SWITCH&&net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(AllBlocks.THRESHOLD_SWITCH).equals(Create.asResource("stockpile_switch")),"Actual pinned source block/BE identity");h.assertTrue(AllBlocks.THRESHOLD_SWITCH.getStateDefinition().getPossibleStates().size()==72,"All three target mounts/four facings/six native visual levels");h.succeed();}
    @GameTest(structure=STRUCTURE) public void emptyRealBarrelCountsEverySlotCapacity(GameTestHelper h){var s=barrel(h);h.assertTrue(s.currentLevel==0&&s.currentMaxLevel==1728&&s.currentMinLevel==0&&s.getTypeOfCurrentTarget()==ThresholdSwitchBlockEntity.ThresholdType.ITEM,"Actual vanilla barrel capacity includes empty slots");h.succeed();}
    @GameTest(structure=STRUCTURE) public void nonStackableCapacityUsesActualComponentLimit(GameTestHelper h){var s=barrel(h);h.getBlockEntity(T,BarrelBlockEntity.class).setItem(0,new ItemStack(Items.DIAMOND_SWORD));s.resetInventoryTracking();s.updateCurrentLevel();h.assertTrue(s.currentLevel==1&&s.currentMaxLevel==1665,"Actual nonstackable slot contributes one capacity, empty slots64");h.succeed();}
    @GameTest(structure=STRUCTURE) public void filterCountsMatchingItemsWithoutChangingCapacity(GameTestHelper h){var s=barrel(h);amount(h,100);h.getBlockEntity(T,BarrelBlockEntity.class).setItem(2,new ItemStack(Items.GOLD_INGOT,32));s.filtering.setFilter(new ItemStack(Items.IRON_INGOT));h.assertTrue(s.currentLevel==100&&s.currentMaxLevel==1728,"Native filter changes measured items only");s.filtering.setFilter(new ItemStack(Items.DIAMOND));h.assertTrue(s.currentLevel==0&&s.currentMaxLevel==1728,"No matching items retain real total capacity");h.succeed();}
    @GameTest(structure=STRUCTURE) public void inclusiveUpperThresholdStartsRealTwoTickOutput(GameTestHelper h){var s=barrel(h);h.assertTrue(s.configure(128,64,false,false),"Valid real thresholds");amount(h,128);h.assertTrue(s.getState()&&!s.isPowered(),"Inclusive raw upper edge precedes actual delayed output");h.runAfterDelay(3,()->{h.assertTrue(s.isPowered(),"Actual scheduled native block tick publishes output");h.succeed();});}
    @GameTest(structure=STRUCTURE) public void hysteresisRetainsStateBetweenBothThresholds(GameTestHelper h){var s=barrel(h);amount(h,128);amount(h,65);h.assertTrue(s.getState(),"Above lower threshold stays on");amount(h,64);h.assertFalse(s.getState(),"Inclusive lower threshold switches off");amount(h,127);h.assertFalse(s.getState(),"Below upper threshold stays off");h.succeed();}
    @GameTest(structure=STRUCTURE) public void delayedFallingEdgeReachesPhysicalRedstone(GameTestHelper h){var s=barrel(h);amount(h,128);h.runAfterDelay(3,()->{amount(h,64);h.assertTrue(s.isPowered()&&!s.getState(),"Raw falling edge retains output for source delay");});h.runAfterDelay(6,()->{h.assertFalse(s.isPowered(),"Native delayed falling edge");h.succeed();});}
    @GameTest(structure=STRUCTURE) public void immediateInversionDoesNotWaitForLazyRefresh(GameTestHelper h){var s=barrel(h);s.setInverted(true);h.assertTrue(s.isPowered()&&s.shouldBePowered(),"Source inversion immediately updates physical output");s.setInverted(false);h.assertFalse(s.isPowered(),"Immediate inversion reversal");h.succeed();}
    @GameTest(structure=STRUCTURE) public void outputExcludesOnlyObservedSide(GameTestHelper h){var s=barrel(h);s.setInverted(true);var pos=h.absolutePos(S);for(var direction:Direction.values())h.assertTrue(h.getBlockState(S).getSignal(h.getLevel(),pos,direction)==(direction==Direction.WEST?0:15),"Source observed side output contract "+direction);h.succeed();}
    @GameTest(structure=STRUCTURE) public void visualLevelZeroAndFullUseNativeStates(GameTestHelper h){barrel(h);h.assertTrue(h.getBlockState(S).getValue(ThresholdSwitchBlock.LEVEL)==0,"Empty is native level0");amount(h,1);h.assertTrue(h.getBlockState(S).getValue(ThresholdSwitchBlock.LEVEL)==1,"Nonempty starts native level1");amount(h,1728);h.assertTrue(h.getBlockState(S).getValue(ThresholdSwitchBlock.LEVEL)==5,"Full is native level5");h.succeed();}
    @GameTest(structure=STRUCTURE) public void lazyRealInventoryRefreshDoesNotNeedNeighbourMutation(GameTestHelper h){barrel(h);h.getBlockEntity(T,BarrelBlockEntity.class).setItem(0,new ItemStack(Items.IRON_INGOT,37));h.runAfterDelay(12,()->{h.assertTrue(sensor(h).currentLevel==37,"Real10tick lazy refresh observes actual container change");h.succeed();});}
    @GameTest(structure=STRUCTURE) public void actualFluidTankUsesSourceMillibuckets(GameTestHelper h){var s=tank(h,2*FluidConstants.BUCKET+81*375);h.assertTrue(s.currentLevel==2375&&s.currentMaxLevel==8000&&s.getTypeOfCurrentTarget()==ThresholdSwitchBlockEntity.ThresholdType.FLUID,"Fabric81000unit buckets become source1000mB, without mutation");h.succeed();}
    @GameTest(structure=STRUCTURE) public void nativeBucketFilterMatchesActualFluidVariant(GameTestHelper h){var s=tank(h,FluidConstants.BUCKET);s.filtering.setFilter(new ItemStack(Items.LAVA_BUCKET));h.assertTrue(s.currentLevel==0&&s.currentMaxLevel==8000,"Fluid filter preserves tank capacity");s.filtering.setFilter(new ItemStack(Items.WATER_BUCKET));h.assertTrue(s.currentLevel==1000,"Actual fluid bucket filter matches water");h.succeed();}
    @GameTest(structure=STRUCTURE) public void realPulleyObservableUsesActualWorldHeightRange(GameTestHelper h){h.setBlock(T,AllBlocks.ROPE_PULLEY);h.setBlock(S,AllBlocks.THRESHOLD_SWITCH.defaultBlockState().setValue(ThresholdSwitchBlock.FACING,Direction.EAST));var s=sensor(h);var pulley=h.getBlockEntity(T,PulleyBlockEntity.class);s.updateCurrentLevel();h.assertTrue(s.getTypeOfCurrentTarget()==ThresholdSwitchBlockEntity.ThresholdType.CUSTOM&&s.currentMinLevel==h.getLevel().getMinY()&&s.currentMaxLevel==h.absolutePos(T).getY()&&s.currentLevel==pulley.getCurrentValue(),"Actual native pulley Observable values take precedence");h.succeed();}
    @GameTest(structure=STRUCTURE) public void realProcessingInventoryAndStockTickerAreExcluded(GameTestHelper h){barrel(h);h.setBlock(T,AllBlocks.BASIN);sensor(h).updateCurrentLevel();h.assertTrue(sensor(h).getTypeOfCurrentTarget()==ThresholdSwitchBlockEntity.ThresholdType.UNSUPPORTED,"Source real ProcessingInventory exclusion");h.setBlock(T,AllBlocks.STOCK_TICKER);sensor(h).updateCurrentLevel();h.assertFalse(sensor(h).hasValidSample(),"Source StockTicker exclusion");h.succeed();}
    @GameTest(structure=STRUCTURE) public void removalOfSupportedTargetClearsRawAfterDelay(GameTestHelper h){var s=barrel(h);amount(h,128);s.updatePowerAfterDelay();h.setBlock(T,Blocks.STONE);s.updateCurrentLevel();h.assertTrue(s.currentLevel==-1&&s.currentMinLevel==-1&&s.currentMaxLevel==-1&&!s.getState()&&s.isPowered(),"Unsupported target keeps actual delayed output until native tick");h.runAfterDelay(3,()->{h.assertFalse(s.isPowered(),"Native unsupported falling output");h.succeed();});}
    @GameTest(structure=STRUCTURE) public void unknownTankControllerPreservesMeasurementAndNoChunkTicket(GameTestHelper h){var s=tank(h,FluidConstants.BUCKET);s.configure(1000,500,false,false);s.updatePowerAfterDelay();var far=new BlockPos(2600000,80,2600000);h.getBlockEntity(T,FluidTankBlockEntity.class).setController(far);s.updateCurrentLevel();h.assertTrue(!s.hasValidSample()&&s.currentLevel==1000&&s.isPowered()&&h.getLevel().getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"Unready real multiblock preserves last measurement/output and requests no remote terrain");h.succeed();}
    @GameTest(structure=STRUCTURE) public void nativePersistenceAcceptsOriginalFloatThresholds(GameTestHelper h){var s=barrel(h);var tag=s.saveWithoutMetadata(h.getLevel().registryAccess());tag.putFloat("OnAboveAmount",155.0f);tag.putFloat("OffBelowAmount",77.0f);load(h,s,tag);h.assertTrue(s.onWhenAbove==155&&s.offWhenBelow==77,"Pinned source float threshold payload migrates through real NumericTag API");tag.putInt("OnAboveAmount",160);tag.putInt("OffBelowAmount",80);load(h,s,tag);h.assertTrue(s.onWhenAbove==160&&s.offWhenBelow==80,"Native int payload roundtrip");h.succeed();}
    @GameTest(structure=STRUCTURE) public void realSaveReloadRestoresConfigFilterAndDelayedState(GameTestHelper h){var s=barrel(h);amount(h,150);s.filtering.setFilter(new ItemStack(Items.IRON_INGOT));h.assertTrue(s.configure(128,64,true,true),"Real stack config");var tag=s.saveWithoutMetadata(h.getLevel().registryAccess());h.setBlock(S,Blocks.AIR);h.setBlock(S,AllBlocks.THRESHOLD_SWITCH.defaultBlockState().setValue(ThresholdSwitchBlock.FACING,Direction.EAST));var restored=sensor(h);load(h,restored,tag);h.assertTrue(restored!=s&&restored.onWhenAbove==128&&restored.offWhenBelow==64&&restored.inStacks&&restored.isInverted()&&restored.filtering.getFilter().is(Items.IRON_INGOT)&&restored.isPowered()==s.isPowered(),"Actual new BE restores original keys and filter");h.succeed();}
    @GameTest(structure=STRUCTURE) public void configRejectsCrossedAndOutsideActualRange(GameTestHelper h){var s=barrel(h);h.assertFalse(s.configure(64,128,false,false)||s.configure(1729,64,false,false)||s.configure(64,-1,false,false)||s.configure(64,64,false,false),"Native bounded configuration rejects invalid thresholds");h.assertTrue(s.onWhenAbove==128&&s.offWhenBelow==64&&!s.isInverted(),"Rejected config is atomic");h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualNativeMenuAcceptsOnlyExactOwnerRevisionAndReach(GameTestHelper h){var s=barrel(h);var p=player(h);ThresholdSwitchMenu.open(p,s);var menu=(ThresholdSwitchMenu)p.containerMenu;var packet=new ConfigureThresholdSwitchPacket(menu.containerId,h.absolutePos(S),menu.opening().revision(),140,70,true,true);h.assertTrue(packet.apply(p)&&s.onWhenAbove==140&&s.offWhenBelow==70&&s.inStacks&&s.isInverted(),"Actual native menu config");h.assertFalse(packet.apply(p),"Replayed native revision rejected");h.assertFalse(new ConfigureThresholdSwitchPacket(menu.containerId+1,h.absolutePos(S),menu.opening().revision(),160,80,false,false).apply(p),"Wrong menu rejected");p.setPos(Vec3.atCenterOf(h.absolutePos(S)).add(80,0,0));h.assertFalse(new ConfigureThresholdSwitchPacket(menu.containerId,h.absolutePos(S),menu.opening().revision(),160,80,false,false).apply(p),"Remote player rejected");p.closeContainer();h.succeed();}
    @GameTest(structure=STRUCTURE) public void replacedNativeOwnerInvalidatesAlreadyOpenMenu(GameTestHelper h){barrel(h);var p=player(h);ThresholdSwitchMenu.open(p,sensor(h));var menu=(ThresholdSwitchMenu)p.containerMenu;h.setBlock(S,Blocks.AIR);h.setBlock(S,AllBlocks.THRESHOLD_SWITCH.defaultBlockState().setValue(ThresholdSwitchBlock.FACING,Direction.EAST));h.assertFalse(new ConfigureThresholdSwitchPacket(menu.containerId,h.absolutePos(S),menu.opening().revision(),140,70,false,false).apply(p),"New block at same position cannot inherit old menu authority");p.closeContainer();h.succeed();}
    @GameTest(structure=STRUCTURE) public void concreteFillLevelLegacyAndAssociationResolve(GameTestHelper h){barrel(h);h.assertTrue(DisplaySource.get(Create.asResource("stockpile_switch_source_fill_level"))==AllDisplaySources.FILL_LEVEL&&DisplaySource.getAll(h.getLevel(),h.absolutePos(S)).contains(AllDisplaySources.FILL_LEVEL),"Actual original legacy source and native block association");h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualMeasuredFillLevelWritesPercentAndEventRefreshToNativeSign(GameTestHelper h){barrel(h);amount(h,864);display(h,false);h.assertTrue(sign(h).equals("50%"),"Actual half-full barrel percent through native DisplayLink/sign");amount(h,1728);h.assertTrue(sign(h).equals("100%"),"Actual measurement event refresh reaches genuine gatherer");h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualProgressBarAndUnknownFrontierPreserveNativeSign(GameTestHelper h){var s=tank(h,4*FluidConstants.BUCKET);var link=display(h,true);String before=sign(h);h.assertTrue(before.contains("█")&&before.contains("▒"),"Genuine half-full progress bar");h.getBlockEntity(T,FluidTankBlockEntity.class).setController(new BlockPos(2600000,80,2600000));s.updateCurrentLevel();link.updateGatheredData();h.assertTrue(sign(h).equals(before),"Unknown real tank frontier defers publishing fabricated empty display");h.succeed();}
    @GameTest(structure=STRUCTURE) public void realWrenchRotatesTargetWithoutOpeningOrDroppingFilter(GameTestHelper h){var s=barrel(h);s.filtering.setFilter(new ItemStack(Items.IRON_INGOT));var p=h.makeMockPlayer(GameType.SURVIVAL);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.WRENCH));var pos=h.absolutePos(S);var result=p.getMainHandItem().useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false)));h.assertTrue(result.consumesAction()&&h.getBlockState(S).getValue(ThresholdSwitchBlock.FACING)!=Direction.EAST&&sensor(h)==s&&s.filtering.getFilter().is(Items.IRON_INGOT),"Actual native wrench route preserves exact BE/filter and rotates target");h.succeed();}
    @GameTest(structure=STRUCTURE) public void originalNativeRecipeAndLootProduceOneActualItem(GameTestHelper h){var input=CraftingInput.of(1,3,List.of(new ItemStack(AllItems.ELECTRON_TUBE),new ItemStack(AllBlocks.BRASS_CASING),new ItemStack(Items.COMPARATOR)));var result=h.getLevel().getServer().getRecipeManager().getRecipeFor(RecipeType.CRAFTING,input,h.getLevel()).orElseThrow().value().assemble(input);h.assertTrue(result.is(AllBlocks.THRESHOLD_SWITCH.asItem())&&result.getCount()==1,"Actual source-shaped recipe");barrel(h);var drops=Block.getDrops(h.getBlockState(S),h.getLevel(),h.absolutePos(S),sensor(h));h.assertTrue(drops.size()==1&&drops.getFirst().is(AllBlocks.THRESHOLD_SWITCH.asItem()),"Real native loot");h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualNativeMenuRejectsChangedTargetSchemaBeforePeriodicBroadcast(GameTestHelper h){var s=barrel(h);var p=player(h);ThresholdSwitchMenu.open(p,s);var menu=(ThresholdSwitchMenu)p.containerMenu;int revision=menu.opening().revision();h.setBlock(T,AllBlocks.FLUID_TANK);s.updateCurrentLevel();h.assertFalse(new ConfigureThresholdSwitchPacket(menu.containerId,h.absolutePos(S),revision,140,70,false,false).apply(p),"Actual freshly changed item-to-fluid target rejects old menu schema even before periodic snapshot");h.assertTrue(s.onWhenAbove==128&&s.offWhenBelow==64&&menu.opening().revision()>revision&&menu.opening().kind()==ThresholdSwitchBlockEntity.ThresholdType.FLUID,"Schema rejection keeps config atomic and refreshes genuine native menu");p.closeContainer();h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualMeasurementSnapshotKeepsConfigurationRevisionUsable(GameTestHelper h){var s=barrel(h);var p=player(h);ThresholdSwitchMenu.open(p,s);var menu=(ThresholdSwitchMenu)p.containerMenu;int revision=menu.opening().revision();amount(h,37);for(int tick=0;tick<10;tick++)menu.broadcastChanges();h.assertTrue(menu.opening().current()==37&&menu.opening().revision()==revision,"Actual reading-only snapshot must preserve native configuration authority revision");h.assertTrue(new ConfigureThresholdSwitchPacket(menu.containerId,h.absolutePos(S),revision,140,70,false,false).apply(p),"Current legitimate editor remains usable while real container count changes");p.closeContainer();h.succeed();}

    private static void nativeBarrelContents(GameTestHelper h,BlockPos target,int count){
        var barrel=h.getBlockEntity(target,BarrelBlockEntity.class);barrel.clearContent();
        for(int slot=0;count>0;slot++){int amount=Math.min(64,count);barrel.setItem(slot,new ItemStack(Items.IRON_INGOT,amount));count-=amount;}
        barrel.setChanged();
    }
    @GameTest(structure=STRUCTURE,maxTicks=40) public void actualSurvivalPlacementKeepsPublishedOwnerAndNativeLazyOutputDisplay(GameTestHelper h){
        h.setBlock(S.below(),Blocks.STONE);h.setBlock(T,Blocks.BARREL);nativeBarrelContents(h,T,64);
        var absolute=h.absolutePos(S);
        ThresholdSwitchBlockEntity placed;
        try(var joined=NativeSurvivalTestPlayer.join(h,Vec3.atCenterOf(absolute).add(0,0,2))){
            var player=joined.player();var stack=new ItemStack(AllBlocks.THRESHOLD_SWITCH);player.setItemInHand(InteractionHand.MAIN_HAND,stack);
            var hit=new BlockHitResult(Vec3.atBottomCenterOf(absolute),Direction.UP,absolute.below(),false);
            h.assertTrue(player.gameMode.useItemOn(player,h.getLevel(),stack,InteractionHand.MAIN_HAND,hit).consumesAction()&&player.getMainHandItem().isEmpty(),"Actual registered survival BlockItem placement pays exactly one native threshold item");
            placed=sensor(h);
            h.assertTrue(placed.getTargetPos().equals(h.absolutePos(T))&&placed.getBlockState()==h.getBlockState(S),"Native item placement returns with one canonical owner matching the actual published section state");
            ThresholdSwitchMenu.open(player,placed);var menu=(ThresholdSwitchMenu)player.containerMenu;
            h.assertTrue(new ConfigureThresholdSwitchPacket(menu.containerId,absolute,menu.opening().revision(),129,32,false,true).apply(player),"Actual native menu configures129/32 inverted after placement publication");player.closeContainer();
            h.assertTrue(placed.currentLevel==64&&placed.currentMaxLevel==1728&&placed.isInverted()&&!placed.getState()&&placed.isPowered()&&placed.getBlockState()==h.getBlockState(S),"Initial legitimate menu measurement preserves canonical native owner/state and source inverted output");
        }
        display(h,false);h.assertTrue(sign(h).equals("3%"),"Actual DisplayLink begins with the measured64/1728 native sign");
        nativeBarrelContents(h,T,129);
        h.runAfterDelay(14,()->{
            h.assertTrue(sensor(h)==placed&&!placed.isRemoved()&&placed.getBlockState()==h.getBlockState(S),"Same paid native owner survives actual visual state publication and ordinary server ticks");
            h.assertTrue(placed.currentLevel==129&&placed.currentMinLevel==0&&placed.currentMaxLevel==1728&&placed.getState()&&placed.isInverted()&&!placed.isPowered(),"Genuine native lazy ticks observe129 and publish exact inclusive hysteresis plus delayed inverted output");
            h.assertTrue(sign(h).equals("7%"),"Genuine native measurement event reaches the actual FillLevel gatherer and native sign without a manual refresh");h.succeed();
        });
    }
    @GameTest(structure=STRUCTURE,maxTicks=40) public void nativePropertyPlacementDefersMeasurementUntilOwnerStatePublication(GameTestHelper h){
        var other=S.south();h.setBlock(T,Blocks.BARREL);nativeBarrelContents(h,T,64);h.setBlock(other,Blocks.BARREL);nativeBarrelContents(h,other,864);
        h.setBlock(S,AllBlocks.THRESHOLD_SWITCH.defaultBlockState().setValue(ThresholdSwitchBlock.FACING,Direction.EAST));var placed=sensor(h);
        h.assertTrue(placed.getBlockState()==h.getBlockState(S),"Native initial block placement leaves the captured owner synchronized before any normal tick");
        h.runAfterDelay(2,()->{
            h.assertTrue(sensor(h)==placed&&placed.currentLevel==64&&placed.getBlockState()==h.getBlockState(S)&&h.getBlockState(S).getValue(ThresholdSwitchBlock.LEVEL)==1,"Only genuine native ticks measure64 and publish coherent visualLEVEL1");
            h.assertTrue(h.getLevel().setBlock(h.absolutePos(S),h.getBlockState(S).setValue(ThresholdSwitchBlock.FACING,Direction.SOUTH),Block.UPDATE_ALL),"Actual native same-block orientation property update succeeds");
            h.assertTrue(sensor(h)==placed&&placed.getBlockState()==h.getBlockState(S)&&placed.getTargetPos().equals(h.absolutePos(other)),"Property onPlace returns with the same canonical owner and exact new native state before remeasurement");
            h.runAfterDelay(14,()->{
                h.assertTrue(sensor(h)==placed&&placed.currentLevel==864&&placed.currentMaxLevel==1728&&placed.getState()&&placed.isPowered(),"Genuine native ticker and scheduled output follow the new physical barrel without direct measurement/ticker calls");
                h.assertTrue(placed.getBlockState()==h.getBlockState(S)&&h.getBlockState(S).getValue(ThresholdSwitchBlock.LEVEL)==3,"Native property callback cannot leave stale cachedLEVEL1 beneath the actual publishedLEVEL3");h.succeed();
            });
        });
    }
}
